with scored as (select *, first_value(country) ignore nulls over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) first_known_country, row_number() over (order by started_at, id) seq_no, row_number() over (partition by country order by started_at desc, id) seq_no_2, first_value(browser) ignore nulls over (partition by device order by started_at, id rows between unbounded preceding and current row) first_known_browser from sessions where browser in ('Chrome', 'Safari', 'Edge')), with_dims as (select a.id, a.customer_id, a.device, a.country, a.first_known_country, a.seq_no_2, a.first_known_browser, c.name, c.city from scored a join customers c on a.customer_id = c.id), enriched as (select id, customer_id, device, country, first_known_country, seq_no_2, name, city, avg(seq_no_2) over (partition by city, device order by seq_no_2, id rows between unbounded preceding and current row) running_avg_seq_no_2, max(seq_no_2) over (partition by city, device order by seq_no_2, id rows between unbounded preceding and current row) running_max_seq_no_2, count(seq_no_2) over (partition by city, device order by seq_no_2, id rows between unbounded preceding and current row) running_count_seq_no_2, rank() over (order by seq_no_2 desc nulls last) seq_no_2_rank from with_dims), deduped as (select * from enriched qualify row_number() over (partition by city order by running_count_seq_no_2 nulls first, id) = 1) select customer_id, case when running_avg_seq_no_2 >= 6.5 then 'LARGE' else 'SMALL' end as running_avg_seq_no_2_tier, sort_array(collect_set(country)) as country_list, sum(case when city = 'Tokyo' then seq_no_2 else 0 end) as tokyo_seq_no_2, round(sum(seq_no_2) / nullif(count(case when device = 'mobile' then 1 end), 0), 2) as seq_no_2_per_mobile, round(avg(running_count_seq_no_2), 2) as avg_running_count_seq_no_2, count(distinct id) as distinct_ids from deduped group by rollup (customer_id, case when running_avg_seq_no_2 >= 6.5 then 'LARGE' else 'SMALL' end) order by avg_running_count_seq_no_2 desc nulls last;
